import{_ as a,a as e,b as t}from"./chunks/scenes.Bx44mSYw.js";import{_ as n,o as m,c as p,a2 as i}from"./chunks/framework.CN568Poi.js";const v=JSON.parse('{"title":"What is in the data","description":"","frontmatter":{},"headers":[],"relativePath":"data.md","filePath":"data.md","lastUpdated":1795431209000}'),l={name:"data.md"};function r(o,s,c,h,d,g){return m(),p("div",null,[...s[0]||(s[0]=[i('<h1 id="what-is-in-the-data" tabindex="-1">What is in the data <a class="header-anchor" href="#what-is-in-the-data" aria-label="Permalink to &quot;What is in the data&quot;">​</a></h1><p>HumanCOIN records the operator&#39;s intent pathway alongside every visual–action pair. This page explains the scientific framing and what a single episode contains.</p><h2 id="a-formal-view" tabindex="-1">A formal view <a class="header-anchor" href="#a-formal-view" aria-label="Permalink to &quot;A formal view&quot;">​</a></h2><p>Let <code>o</code> be the observation, <code>a</code> the action and <code>z</code> the operator&#39;s latent intent. A standard policy marginalises <code>z</code> away:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>p</mi><mo stretchy="false">(</mo><mi>a</mi><mo>∣</mo><mi>o</mi><mo stretchy="false">)</mo><mo>=</mo><mo>∫</mo><mi>p</mi><mo stretchy="false">(</mo><mi>a</mi><mo>∣</mo><mi>o</mi><mo separator="true">,</mo><mi>z</mi><mo stretchy="false">)</mo><mtext> </mtext><mi>p</mi><mo stretchy="false">(</mo><mi>z</mi><mo>∣</mo><mi>o</mi><mo stretchy="false">)</mo><mtext> </mtext><mi mathvariant="normal">d</mi><mi>z</mi><mi mathvariant="normal">.</mi></mrow><annotation encoding="application/x-tex">p(a \\mid o) = \\int p(a \\mid o, z)\\, p(z \\mid o)\\, \\mathrm{d}z . </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.2222em;vertical-align:-0.8622em;"></span><span class="mop op-symbol large-op" style="margin-right:0.44445em;position:relative;top:-0.0011em;">∫</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.04398em;">z</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.04398em;">z</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathrm">d</span><span class="mord mathnormal" style="margin-right:0.04398em;">z</span><span class="mord">.</span></span></span></span></span></p><p>HumanCOIN does not observe <code>z</code> directly. It records a vector of proxies along the intent pathway:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>m</mi><mi>j</mi></msub><mo>=</mo><msub><mi>f</mi><mi>j</mi></msub><mo stretchy="false">(</mo><msub><mi>z</mi><mi>j</mi></msub><mo separator="true">,</mo><mi>o</mi><mo stretchy="false">)</mo><mo>+</mo><msub><mi>ε</mi><mi>j</mi></msub><mo separator="true">,</mo><mspace width="2em"></mspace><mi>j</mi><mo>∈</mo><mo stretchy="false">{</mo><mrow><mi mathvariant="normal">g</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">z</mi><mi mathvariant="normal">e</mi></mrow><mo separator="true">,</mo><mtext> </mtext><mrow><mi mathvariant="normal">e</mi><mi mathvariant="normal">m</mi><mi mathvariant="normal">g</mi></mrow><mo separator="true">,</mo><mtext> </mtext><mrow><mi mathvariant="normal">e</mi><mi mathvariant="normal">e</mi><mi mathvariant="normal">g</mi></mrow><mo stretchy="false">}</mo><mo separator="true">,</mo></mrow><annotation encoding="application/x-tex">m_j = f_j(z_j, o) + \\varepsilon_j, \\qquad j \\in \\{\\mathrm{gaze},\\ \\mathrm{emg},\\ \\mathrm{eeg}\\}, </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">m</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.05724em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.10764em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.05724em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.04398em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.05724em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">o</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9456em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">ε</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.05724em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.05724em;">j</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathrm">gaze</span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm" style="margin-right:0.01389em;">emg</span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm" style="margin-right:0.01389em;">eeg</span></span><span class="mclose">}</span><span class="mpunct">,</span></span></span></span></span></p><p>where <code>f_j</code> is a lossy, sensor-specific readout and <code>ε_j</code> is noise; <code>m</code> is not a sufficient statistic for <code>z</code>. The corpus supports two supervised problems:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><munder><mrow><mi>max</mi><mo>⁡</mo></mrow><mi>ϕ</mi></munder><mtext> </mtext><msub><mi mathvariant="double-struck">E</mi><mrow><mo stretchy="false">(</mo><mi>o</mi><mo separator="true">,</mo><mi>m</mi><mo stretchy="false">)</mo></mrow></msub><mrow><mo fence="true">[</mo><mi>log</mi><mo>⁡</mo><msub><mi>p</mi><mi>ϕ</mi></msub><mo stretchy="false">(</mo><mi>m</mi><mo>∣</mo><mi>o</mi><mo stretchy="false">)</mo><mo fence="true">]</mo></mrow><mo separator="true">,</mo><mspace width="2em"></mspace><munder><mrow><mi>max</mi><mo>⁡</mo></mrow><mi>θ</mi></munder><mtext> </mtext><msub><mi mathvariant="double-struck">E</mi><mrow><mo stretchy="false">(</mo><mi>o</mi><mo separator="true">,</mo><mi>m</mi><mo separator="true">,</mo><mi>a</mi><mo stretchy="false">)</mo></mrow></msub><mrow><mo fence="true">[</mo><mi>log</mi><mo>⁡</mo><msub><mi>p</mi><mi>θ</mi></msub><mo stretchy="false">(</mo><mi>a</mi><mo>∣</mo><mi>o</mi><mo separator="true">,</mo><mi>m</mi><mo stretchy="false">)</mo><mo fence="true">]</mo></mrow><mi mathvariant="normal">.</mi></mrow><annotation encoding="application/x-tex">\\max_\\phi\\ \\mathbb{E}_{(o,m)}\\left[\\log p_\\phi(m \\mid o)\\right], \\qquad \\max_\\theta\\ \\mathbb{E}_{(o,m,a)}\\left[\\log p_\\theta(a \\mid o, m)\\right]. </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.6382em;vertical-align:-0.8882em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.3479em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">max</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8882em;"><span></span></span></span></span></span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight">o</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">m</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">[</span><span class="mop">lo<span style="margin-right:0.01389em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">m</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">o</span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">]</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.3479em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.02778em;">θ</span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">max</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7521em;"><span></span></span></span></span></span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight">o</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">m</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">a</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">[</span><span class="mop">lo<span style="margin-right:0.01389em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.02778em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">m</span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">]</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">.</span></span></span></span></span></p><p>The first learns a proxy model; the second learns a proxy-conditioned policy. The question of interest is whether <code>m</code> carries information about <code>a</code> beyond <code>o</code>:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>I</mi><mo stretchy="false">(</mo><mi>a</mi><mo separator="true">;</mo><mi>m</mi><mo>∣</mo><mi>o</mi><mo stretchy="false">)</mo><mo>=</mo><mi mathvariant="double-struck">E</mi><mo stretchy="false">[</mo><mi>log</mi><mo>⁡</mo><mi>p</mi><mo stretchy="false">(</mo><mi>a</mi><mo>∣</mo><mi>o</mi><mo separator="true">,</mo><mi>m</mi><mo stretchy="false">)</mo><mo>−</mo><mi>log</mi><mo>⁡</mo><mi>p</mi><mo stretchy="false">(</mo><mi>a</mi><mo>∣</mo><mi>o</mi><mo stretchy="false">)</mo><mo stretchy="false">]</mo><mi mathvariant="normal">.</mi></mrow><annotation encoding="application/x-tex">I(a; m \\mid o) = \\mathbb{E}[\\log p(a \\mid o, m) - \\log p(a \\mid o)]. </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.07847em;">I</span><span class="mopen">(</span><span class="mord mathnormal">a</span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">m</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathbb">E</span><span class="mopen">[</span><span class="mop">lo<span style="margin-right:0.01389em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">m</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">lo<span style="margin-right:0.01389em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mclose">)]</span><span class="mord">.</span></span></span></span></span></p><p align="center"><img src="'+a+'" alt="Action policy, world model and proxy-conditioned intent" width="620"><br><sub>An action policy folds intent into its weights; a world model predicts the future; HumanCOIN records proxies for intent. Figure from the technical report.</sub></p><h2 id="three-tiers" tabindex="-1">Three tiers <a class="header-anchor" href="#three-tiers" aria-label="Permalink to &quot;Three tiers&quot;">​</a></h2><p>Each tier inherits every proxy of the tier below and adds one more. Hours decrease with signal depth.</p><table tabindex="0"><thead><tr><th>Tier</th><th>Hours</th><th>Added proxy</th><th>Typical streams</th><th>Setting</th><th>Scenes</th></tr></thead><tbody><tr><td><strong>L1 · Attention</strong></td><td>10,000</td><td>gaze estimated from headband video</td><td>2–6 head cameras, depth, pose</td><td>open, unscripted</td><td>38</td></tr><tr><td><strong>L2 · Exertion</strong></td><td>2,000</td><td>bilateral sEMG, 8 ch/arm @ 2 kHz</td><td>4-camera headband, 2 wrist views</td><td>open, task sheets</td><td>21</td></tr><tr><td><strong>L3 · Cognition</strong></td><td>500</td><td>EEG 128 ch @ 1 kHz (controlled) or 32/8 ch @ 250 Hz (open)</td><td>4 head + 2 wrist + eye + third-person, eye tracker, trackers, gloves</td><td>≈350 h controlled + ≈150 h open</td><td>9</td></tr></tbody></table><p>L1 has no EMG or EEG; L2 adds EMG; L3 adds EEG and, in its controlled subset, direct measurements of gaze, head/wrist pose and finger kinematics. Those measurements are the <strong>reference</strong> for the estimates used in shallower tiers — not ground truth for intent.</p><h2 id="one-episode" tabindex="-1">One episode <a class="header-anchor" href="#one-episode" aria-label="Permalink to &quot;One episode&quot;">​</a></h2><p align="center"><img src="'+e+'" alt="Anatomy of one controlled L3 episode" width="100%"><br><sub>One controlled L3 episode at t = 27.6 s: point cloud and 6-DoF poses, synchronized views, step annotation, and gaze/EMG/EEG on one time axis. Figure from the technical report.</sub></p><h3 id="views-and-geometry" tabindex="-1">Views and geometry <a class="header-anchor" href="#views-and-geometry" aria-label="Permalink to &quot;Views and geometry&quot;">​</a></h3><ul><li><strong>Head cameras.</strong> L1 uses 14 third-party headbands from 13 vendors: 2–6 lenses, 20–60 fps, from 512×512 rectified to 3840×1200. L2/L3 use a four-lens headband at 1920×1200 and 30 fps; the front pair is hardware-synchronized. Released streams may be downscaled — read the shape from <code>meta/info.json</code>.</li><li><strong>Wrist and third-person.</strong> L2 adds two wrist views. L3 adds two 640×480 wrist cameras, a 1600×1200 eye-tracker scene camera, and a third-person RGB-D view in the controlled subset.</li><li><strong>Depth and point clouds.</strong> Depth is reconstructed from the front stereo pair with FoundationStereo, stored with the intrinsics that produced it, and projected per frame. Camera views are released raw and rectified where the release provides both.</li><li><strong>Pose and hands.</strong> Head, wrists and chest share one metric frame: <code>+x</code> left, <code>+y</code> up, <code>+z</code> forward; translations in millimetres, joint angles in degrees. Pose streams use either 7 values (position + quaternion) or 6 values (position + Euler angles); read <code>names</code>. Controlled L3 uses three 6-DoF trackers and 20-node gloves; elsewhere pose and hands are estimated from video.</li></ul><h3 id="intent-proxies" tabindex="-1">Intent proxies <a class="header-anchor" href="#intent-proxies" aria-label="Permalink to &quot;Intent proxies&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Proxy</th><th>Stream (typical)</th><th>Rate</th><th>Measured or estimated</th></tr></thead><tbody><tr><td>Gaze</td><td><code>observation.eye_gaze</code> (controlled L3); <code>eye_gaze_predict</code> (elsewhere)</td><td>200 Hz measured; 30 Hz estimated</td><td>measured in controlled L3</td></tr><tr><td>Surface EMG</td><td><code>observation.left_wrist_emg</code>, <code>right_wrist_emg</code>, raw/denoised variants</td><td>2 kHz, 8 ch/arm</td><td>measured from L2</td></tr><tr><td>EEG</td><td><code>observation.eeg_raw</code>, <code>eeg_denoise</code></td><td>1 kHz × 132 (128-ch cap); 250 Hz × 32/8</td><td>measured at L3</td></tr></tbody></table><p>Gaze is a pixel coordinate in the eye-tracker scene camera (controlled L3) or the rectified head view. EMG is released as raw and denoised traces; derive an envelope if needed. EEG is released as acquired, filtered and repaired where available. Exact keys vary by release — print <code>ds.meta.features</code>.</p><h3 id="scenes" tabindex="-1">Scenes <a class="header-anchor" href="#scenes" aria-label="Permalink to &quot;Scenes&quot;">​</a></h3><p align="center"><img src="'+t+'" alt="One head-camera frame from each of the 38 scene classes" width="90%"><br><sub>One head-camera frame per scene class, grouped by zone. Figure from the technical report.</sub></p><p>The corpus spans 38 scene classes in five zones — residential, commercial, professional, industrial and public — plus one residual class. L3 contracts to nine classes that can host a fixed desk, stable lighting and a bounded session.</p><h3 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h3><p>Annotation is step-level. Every step carries a sentence, a <strong>task verb</strong> (99 classes), a working hand, the objects it touches, and <strong>motion verbs</strong> (46 classes, on average 2.5 per step). At L2/L3 the object record can include measured shape, size, weight, material and colour.</p><p>Episodes also carry timed task stages, key events, state changes, and — in controlled L3 — phase markers for imagery and execution. Annotation ships as structured JSON and as LeRobot language columns.</p>',29)])])}const b=n(l,[["render",r]]);export{v as __pageData,b as default};
